/*
 * 🐍 Змейка для ESP32-S3 + ST7789 1.54" (240x240) + аналоговый джойстик
 * Библиотеки: Adafruit GFX + Adafruit ST7735/ST7789
 */

#include <Adafruit_GFX.h>
#include <Adafruit_ST7789.h>
#include <SPI.h>

// ---------- Пины дисплея ----------
#define TFT_MOSI   9
#define TFT_SCLK   8
#define TFT_CS    12
#define TFT_DC    11
#define TFT_RST   10
#define TFT_BL    13

// ---------- Пины джойстика ----------
#define JOY_X     21
#define JOY_Y     20
#define JOY_SW    19

// ---------- Параметры игры ----------
#define CELL_SIZE  10
#define GRID_COLS  22
#define GRID_ROWS  22
#define OFFSET_X   10   // отступ под рамку
#define OFFSET_Y   10
#define MAX_SNAKE  256

// ---------- Цвета (RGB565) ----------
#define COL_BG      0x0000   // чёрный
#define COL_BORDER  0x0410   // тёмно-синий
#define COL_SNAKE   0x07E0   // зелёный
#define COL_HEAD    0x07FF   // голубой
#define COL_FOOD    0xF800   // красный
#define COL_TEXT    0xFFFF   // белый

// ---------- Объекты ----------
SPIClass spi(FSPI);
Adafruit_ST7789 tft = Adafruit_ST7789(&spi, TFT_CS, TFT_DC, TFT_RST);

struct Point { int8_t x, y; };

Point snake[MAX_SNAKE];
int   snakeLen   = 3;
int   dirX = 1,  dirY = 0;         // текущее направление
int   nextDirX = 1, nextDirY = 0;  // буфер ввода (не даём развернуться за один тик)
Point food;
int   score = 0;
bool  gameOver = false;
int   gameSpeed = 220;             // мс/тик (уменьшается по мере роста)
unsigned long lastTick = 0;

int  joyCX = 2048, joyCY = 2048;   // центр джойстика (калибруется в setup)
const int JOY_THRESH = 1200;       // порог срабатывания

// =====================================================
// Утилиты пиксельной отрисовки
// =====================================================
inline int cellPx(int gx) { return OFFSET_X + gx * CELL_SIZE; }
inline int cellPy(int gy) { return OFFSET_Y + gy * CELL_SIZE; }

void eraseCell(int gx, int gy) {
  tft.fillRect(cellPx(gx), cellPy(gy), CELL_SIZE, CELL_SIZE, COL_BG);
}

void drawCell(int gx, int gy, uint16_t color) {
  // 1px отступ — эффект сетки
  tft.fillRect(cellPx(gx) + 1, cellPy(gy) + 1,
               CELL_SIZE - 2, CELL_SIZE - 2, color);
}

bool isSnakeAt(int x, int y) {
  for (int i = 0; i < snakeLen; i++)
    if (snake[i].x == x && snake[i].y == y) return true;
  return false;
}

// =====================================================
// Рисование
// =====================================================
void drawBorder() {
  // Внешняя рамка
  tft.drawRect(0, 0, 240, 240, COL_BORDER);
  tft.drawRect(1, 1, 238, 238, COL_BORDER);
  // Граница игрового поля
  tft.drawRect(OFFSET_X - 1, OFFSET_Y - 1,
               GRID_COLS * CELL_SIZE + 2,
               GRID_ROWS * CELL_SIZE + 2, COL_BORDER);
}

void drawScore() {
  tft.fillRect(2, 1, 70, 8, COL_BG);
  tft.setTextColor(COL_TEXT, COL_BG);
  tft.setTextSize(1);
  tft.setCursor(4, 1);
  tft.print("SCORE:");
  tft.print(score);
}

void drawSnakeFull() {
  for (int i = 0; i < snakeLen; i++)
    drawCell(snake[i].x, snake[i].y, (i == 0) ? COL_HEAD : COL_SNAKE);
}

void generateFood() {
  for (int tries = 0; tries < 500; tries++) {
    int fx = random(0, GRID_COLS);
    int fy = random(0, GRID_ROWS);
    if (!isSnakeAt(fx, fy)) {
      food.x = fx; food.y = fy;
      drawCell(food.x, food.y, COL_FOOD);
      return;
    }
  }
  // Если места нет — победа!
  gameOver = true;
}

// =====================================================
// Логика
// =====================================================
void resetGame() {
  tft.fillScreen(COL_BG);
  drawBorder();

  snakeLen = 3;
  snake[0] = { (int8_t)(GRID_COLS / 2),     (int8_t)(GRID_ROWS / 2) };
  snake[1] = { (int8_t)(GRID_COLS / 2 - 1), (int8_t)(GRID_ROWS / 2) };
  snake[2] = { (int8_t)(GRID_COLS / 2 - 2), (int8_t)(GRID_ROWS / 2) };

  dirX = nextDirX = 1;
  dirY = nextDirY = 0;

  score = 0;
  gameSpeed = 220;
  gameOver = false;

  generateFood();
  drawSnakeFull();
  drawScore();

  lastTick = millis();
}

void handleInput() {
  int xv = analogRead(JOY_X);
  int yv = analogRead(JOY_Y);
  int dx = xv - joyCX;
  int dy = yv - joyCY;

  int ndx = nextDirX, ndy = nextDirY;

  if (abs(dx) > abs(dy)) {
    if      (dx >  JOY_THRESH) { ndx =  1; ndy = 0; }
    else if (dx < -JOY_THRESH) { ndx = -1; ndy = 0; }
  } else {
    if      (dy >  JOY_THRESH) { ndx = 0; ndy =  1; }
    else if (dy < -JOY_THRESH) { ndx = 0; ndy = -1; }
  }

  // запрет мгновенного разворота на 180°
  if (ndx == -dirX && ndy == -dirY) return;

  nextDirX = ndx;
  nextDirY = ndy;
}

void updateGame() {
  dirX = nextDirX;
  dirY = nextDirY;

  Point newHead = { (int8_t)(snake[0].x + dirX),
                    (int8_t)(snake[0].y + dirY) };

  // столкновение со стеной
  if (newHead.x < 0 || newHead.x >= GRID_COLS ||
      newHead.y < 0 || newHead.y >= GRID_ROWS) {
    gameOver = true;
    return;
  }

  bool eating = (newHead.x == food.x && newHead.y == food.y);

  // столкновение с собой (хвост «уезжает» — его не считаем, если не едим)
  int limit = eating ? snakeLen : snakeLen - 1;
  for (int i = 0; i < limit; i++) {
    if (snake[i].x == newHead.x && snake[i].y == newHead.y) {
      gameOver = true;
      return;
    }
  }

  Point oldTail = snake[snakeLen - 1];
  Point oldHead = snake[0];

  if (eating) {
    if (snakeLen < MAX_SNAKE) snakeLen++;
    score += 10;
    if (gameSpeed > 70) gameSpeed -= 5;   // плавное ускорение
    drawScore();
    generateFood();
  }

  // сдвиг тела
  for (int i = snakeLen - 1; i > 0; i--) snake[i] = snake[i - 1];
  snake[0] = newHead;

  // отрисовка изменений
  if (!eating) eraseCell(oldTail.x, oldTail.y);
  drawCell(oldHead.x, oldHead.y, COL_SNAKE);   // старая голова → тело
  drawCell(newHead.x, newHead.y, COL_HEAD);    // новая голова
}

// =====================================================
// Экран Game Over
// =====================================================
void drawGameOverScreen() {
  const int w = 190, h = 66;
  const int x = (240 - w) / 2;
  const int y = (240 - h) / 2;

  tft.fillRect(x, y, w, h, COL_BG);
  tft.drawRect(x,     y,     w,     h,     COL_FOOD);
  tft.drawRect(x + 1, y + 1, w - 2, h - 2, COL_FOOD);

  tft.setTextSize(2);
  tft.setTextColor(COL_FOOD, COL_BG);
  tft.setCursor(x + 20, y + 10);
  tft.print("GAME OVER");

  tft.setTextSize(1);
  tft.setTextColor(COL_TEXT, COL_BG);
  tft.setCursor(x + 62, y + 40);
  tft.print("Score: ");
  tft.print(score);
  tft.setCursor(x + 18, y + 52);
  tft.print("Press button to restart");
}

// =====================================================
// setup / loop
// =====================================================
void setup() {
  Serial.begin(115200);

  // подсветка
  pinMode(TFT_BL, OUTPUT);
  digitalWrite(TFT_BL, HIGH);

  // кнопка джойстика
  pinMode(JOY_SW, INPUT_PULLUP);
  analogReadResolution(12);

  // инициализация SPI на кастомных пинах и дисплея
  spi.begin(TFT_SCLK, -1 /*MISO*/, TFT_MOSI, TFT_CS);
  tft.init(240, 240);
  tft.setRotation(0);
  tft.fillScreen(COL_BG);

  // калибровка центра джойстика (усредняем, чтобы не было дрейфа)
  long sx = 0, sy = 0;
  for (int i = 0; i < 16; i++) {
    sx += analogRead(JOY_X);
    sy += analogRead(JOY_Y);
    delay(3);
  }
  joyCX = sx / 16;
  joyCY = sy / 16;
  Serial.printf("Joystick center: X=%d  Y=%d\n", joyCX, joyCY);

  randomSeed(esp_random());
  resetGame();
}

void loop() {
  if (!gameOver) {
    handleInput();

    unsigned long now = millis();
    if (now - lastTick >= (unsigned long)gameSpeed) {
      updateGame();
      lastTick = now;
    }
  } else {
    drawGameOverScreen();
    // ждём нажатия кнопки джойстика
    while (digitalRead(JOY_SW) == HIGH) delay(20);
    delay(300);  // антидребезг
    resetGame();
  }
  delay(5);
}
